        '1. 취업규칙 불이익변경의 의의와 판단기준\n근로기준법 제94조 제1항은 취업규칙을 근로자에게 불리하게 변경하는 경우 근로자 과반수로 조직된 노동조합, 그러한 노동조합이 없으면 근로자 과반수의 동의를 받도록 한다. 불리한지 여부는 변경 시점을 기준으로 근로조건이나 복무규율이 저하되는지를 객관적으로 판단하고, 일부 근로자에게 유리하고 일부에게 불리하여 이익이 충돌하면 불이익변경으로 보아 집단적 동의를 요구하는 것이 판례의 태도이다.',
        '2. 직급정년 신설의 불이익성\n종전 규정은 만 60세 정년만 두었으나, 변경 규정은 과장에서 부장까지 7년간 승진하지 못하면 60세 이전이라도 퇴직하도록 하였다. 이는 근로관계의 존속 자체를 단축하는 것으로서 근로조건 중 가장 중대한 고용의 지속을 박탈하므로 불이익변경에 해당한다. 인사적체 해소라는 목적은 불이익성을 부정하는 사유가 아니라 아래 예외(합리성) 판단에서 고려할 사정에 불과하다.',
        '3. 동의의 주체와 방법\n(1) 주체: 동의 주체는 변경된 취업규칙의 적용을 받는 근로자집단이다. 직급정년은 현재 과장·차장뿐 아니라 장차 승진하여 과장 이상이 될 사원·대리에게도 적용이 예상되므로, 이들을 포함한 전체 근로자집단의 과반수를 기준으로 하는 것이 타당하다(일반직도 승진하면 관리직 정년규정을 적용받게 되므로 전체 직원이 동의 주체라고 본 대법원 2009. 5. 28. 선고 2009두2238 판결).\n(2) 방법: 과반수 노동조합이 없으면 근로자들의 회의방식에 의한 과반수 동의, 즉 사용자의 개입이나 간섭이 배제된 상태에서 근로자 상호간 의견을 교환하여 찬반을 집약하는 집단적 의사결정방식이 필요하다(대법원 1977. 7. 26. 선고 77다355 판결). 사안에서 과반수 노동조합의 존재는 나타나 있지 않으므로 근로자 과반수의 집단적 동의가 필요하다.',
