        '5. 사회통념상 합리성에 의한 예외(시험 당시 판례)\n시험 당시 판례는 집단적 동의가 없더라도 변경의 필요성과 내용 양면에서 사회통념상 합리성이 인정되면 예외적으로 유효하다고 보았다. 판단요소는 ① 근로자가 입는 불이익의 정도, ② 사용자 측의 변경 필요성의 내용과 정도, ③ 변경 후 내용의 상당성, ④ 대상조치 등 관련 근로조건의 개선 상황, ⑤ 노동조합 등과의 교섭 경위와 다른 근로자들의 대응, ⑥ 동종 사항에 관한 국내 일반 상황이며, 동의 요건을 배제하는 예외이므로 엄격하게 해석한다.\n사안에서 인사적체 해소의 필요성은 인정되나, 그 수단이 승진 탈락만으로 고용을 종료시키는 것으로서 불이익이 매우 중대하고, 보상·전직지원·임금피크 등 대상조치가 없으며, 근로자 집단의 의사를 확인하려는 절차도 거치지 않았다. 따라서 사회통념상 합리성도 인정하기 어렵다.\n※ 이후 판례 변경: 대법원 2023. 5. 11. 선고 2017다35588, 35595 전원합의체 판결은 사회통념상 합리성 법리를 폐기하고, 노동조합이나 근로자들이 동의권을 남용한 경우에만 동의 없는 불이익변경의 효력을 인정한다. 현재 법리에 의하더라도 결론은 같다.',
        '6. 동의 없는 불이익변경의 효력 범위\n집단적 동의 없는 불이익변경은 변경 전부터 근무하던 기존 근로자에 대하여는 효력이 없어 종전 취업규칙이 적용되지만, 변경 후 새로 입사한 근로자에 대하여는 변경된 취업규칙이 적용되고, 취업규칙 자체는 하나의 규범으로서 유효하게 존재한다(대법원 1992. 12. 22. 선고 91다45165 전원합의체 판결). 따라서 변경된 제5조 제2항은 2010. 1. 31. 이후 입사자에게는 효력이 있으나, 그 이전부터 근무한 甲 등 기존 근로자에게는 효력이 없다.',
