        '3. 설립신고를 하지 않은 점의 영향\n지부노동조합은 합법적으로 설립된 전국금속산업노동조합의 하부조직이므로 산별노조 자체가 노조법상 노동조합으로서 보호를 받는다. 노조법 시행령 제7조는 근로조건 결정권이 있는 독립된 사업장의 지부·분회가 설립신고를 "할 수 있다"고 규정할 뿐 의무로 하지 않는다. 따라서 설립신고가 없다는 사정만으로 지부의 단체교섭 당사자성이나 쟁의행위 주체성이 부정되지 않는다. 다만 설립신고를 하지 않은 지부는 독자적으로 노동위원회에 부당노동행위 구제를 신청하는 등 노조법상 노동조합으로서의 절차적 지위를 누리는 데에는 제한이 있을 수 있다(노조법 제7조 참조).',
