        '1. 제명의 효력\n규약 제35조 자체는 총회 의결 위반을 제명 사유로 정한 것으로서 일반적으로 무효라고 할 수는 없으나, 그 적용 범위는 통제권의 한계 내로 한정하여 해석하여야 한다. 甲이 위반한 결의는 조합원에게 구속력이 없는 정치적 결의이고, 甲의 행위는 개인의 정치적 기본권 행사이므로 규약 제35조의 "총회의 의결에 위반한 자"에 해당하지 않거나, 해당한다 하더라도 그 제명은 통제권의 한계를 일탈하고 노조법 제9조에 반하여 무효이다. 절차가 정당하였다는 사정은 실체적 하자를 치유하지 못한다. 더욱이 경고 등 가벼운 처분이 가능함에도 곧바로 제명한 것은 비례원칙에도 반한다.',
