        '2. 제안제도와 위원회 구조\n① 부서별 생산위원회(production committee): 감독자와 근로자 대표로 구성되어 현장 개선 제안을 접수·검토하고 일정 범위는 직접 실행한다. ② 심사위원회(screening committee): 경영진과 근로자 대표로 구성되어 부서 차원을 넘는 제안을 심사하고, 매월 성과배분 결과를 검토·공표한다. 개인 제안에 대한 별도 포상보다 집단 성과배분을 통해 보상한다는 점이 일반 제안제도와 다르다.',
