        '2. 행동지표와 수준 정의\n각 역량을 관찰 가능한 행동지표로 정의하고, 수준별(예: 1~5단계) 기대 행동을 기술한 행동기준평정척도(BARS)나 행동관찰척도(BOS)를 사용하여 평가자의 주관을 줄인다.',
