        '4. 평가자 교육과 공정성 확보\n후광효과·관대화·중심화·최근효과 등 평가오류를 줄이기 위한 평가자 훈련과 평가 조정(calibration) 회의를 실시하고, 평가 기준·절차를 공개하며 이의제기 절차를 마련하여 절차적 공정성을 확보한다.',
