      detailed: '거부처분에 대한 의무이행재결은 행정심판위원회의 시정명령과 직접처분으로, 거부처분 취소판결은 법원의 간접강제로 실효성이 담보된다. 그러나 직접처분은 처분의 성질상 한계가 있고, 간접강제는 배상금이 심리적 강제수단에 그친다는 판례로 인해 실효성이 약하다. 따라서 기속력 위반 재처분의 무효 법리, 국가배상 등 보완수단을 함께 활용하고, 입법적으로 행정심판의 간접강제와 의무이행소송 도입을 검토할 필요가 있다.',
