      title: 'Ⅰ. 서론: 처분권주의와 그 한계',
      detailed: '취소소송은 일반적으로 법원의 종국판결로 종료되지만, 당사자의 행위나 사건으로 판결 없이 종료될 수도 있다. 행정소송법은 이에 관하여 특별 규정을 두지 않으므로 같은 법 제8조 제2항에 따라 민사소송법이 준용된다. 민사소송에서는 처분권주의에 따라 당사자가 소송의 개시·범위·종료를 결정할 수 있으나, 취소소송은 행정의 적법성 통제라는 공익적 성격을 가지며 피고 행정청은 법률에 의하여 처분권한을 행사할 뿐 처분을 자유롭게 처분할 수 없다(법치행정, 행정의 법률적합성). 따라서 민사소송법상의 종료 사유를 취소소송에 그대로 적용할 수 있는지가 사유별로 문제된다. 소의 취하, 청구의 포기·인낙, 소송상 화해, 당사자의 소멸 순으로 검토한다.',
