        '퀸은 조직효과성 연구에서 출발한 경쟁가치모형(Competing Values Framework)으로 조직문화를 유형화하였다. 한 축은 "유연성·재량 ↔ 안정성·통제", 다른 축은 "내부 지향·통합 ↔ 외부 지향·차별화"이며, 각 사분면의 가치는 서로 경쟁하는 관계에 있다.\n\n                  유연성·재량\n         집단(관계) 문화 │ 발전(혁신) 문화\n  내부 ──────────────────┼────────────────── 외부\n         위계 문화       │ 합리(시장) 문화\n                  안정성·통제',
