    {
      title: 'Ⅳ. 결론',
      detailed: '노동수요의 탄력성은 생산물 수요탄력성, 요소 대체 용이성, 다른 요소의 공급탄력성 등 파생수요의 성격에 의해 결정된다. 대체요소 가격 상승과 기술진보는 대체효과와 규모효과가 상반되어 노동수요에 대한 영향이 불확정적이며, 생산물 수요 상승은 노동수요를 증가시킨다. 노동공급 측면에서는 근로시간 선택의 신축성이 개인의 효용과 경제활동참가율을 높이므로, 시간제 근로의 질을 보장하는 제도와 함께 신축적 근로시간 제도를 확대하는 것이 노동공급 확대에 바람직하다.',
      compressed: '탄력성 = 파생수요 성격 / 대체요소가격·기술진보 = 대체 vs 규모 → 불확정, 생산물 수요↑ → L↑ / 신축성 → 효용·참가율↑ + 시간제 질 보장'
    }
