        '2. 수요독점 노동시장\n노동의 유일한 구매자인 수요독점기업은 우상향하는 시장 노동공급곡선(S = 평균노동비용 AC_L)에 직면한다. 고용을 한 단위 늘리려면 임금을 올려야 하고 그 인상된 임금을 기존 근로자에게도 지급해야 하므로 한계노동비용(MC_L)곡선이 공급곡선보다 위에 위치한다(MC_L > w). 기업은 MRP_L = MC_L이 되는 점 A에서 고용량 L_m을 정하고, 그 고용량을 공급하게 하는 최저 임금인 공급곡선상의 w_m을 지급한다.\n\n  임금 ↑         MC_L\n       │        ╱    S(=AC_L)\n   w_e ┤······A    ╱\n       │      │╲ ╱ E_c\n   w_c ┤······│·╳·······\n       │      │╱ ╲\n   w_m ┤·····B      ╲ D(=MRP_L=VMP_L)\n       └──────┴──┴────────→ 고용\n             L_m L_c',
