        '보론(임금 하한): w_m < w̄ ≤ w_c → 고용↑(최대 L_c) / w_c < w̄ ≤ w_e → L_m 이상 유지 → 최저임금 논의',
        '결론: 교섭으로 고용 감소 없이 임금↑ 가능'
