      title: 'Ⅳ. 결론',
      detailed: '생산물시장이 완전경쟁일 때 노동시장이 수요독점이면 경쟁시장보다 임금과 고용이 모두 낮고 수요독점적 착취가 발생한다. 노동조합이 공급독점으로 맞서는 쌍방독점에서는 임금이 교섭력에 따라 결정되며, 고용량 L_m에서 w_m부터 w_e까지는 고용 변화 없이 임금이 상승할 수 있다. 이는 노동조합과 최저임금이 수요독점 시장에서는 고용을 해치지 않고 분배를 개선할 수 있음을 시사한다.',
