      title: 'Ⅰ. 효율성 임금의 의의',
      detailed: '효율성 임금(efficiency wage)이란 기업이 노동시장의 수요와 공급을 일치시키는 시장청산임금보다 의도적으로 높게 지급하는 임금이다. 효율성 임금 이론은 임금이 비용일 뿐 아니라 근로자의 생산성(노력)을 높이는 수단이라고 보며, 기업은 임금 1원당 효율성 단위(노력)를 극대화하는 임금을 선택한다. 그 결과 임금 1% 인상에 따른 노력의 증가율이 1%가 되는 수준(노력의 임금탄력성 = 1, 솔로우 조건)에서 임금이 결정된다. 이 임금은 시장청산임금보다 높고 하방경직적이므로 비자발적 실업을 설명하는 근거가 된다.',
